import { existsSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { docSlug } from './doc-slug.ts';
import type { ProjectData } from './project-data.ts';
import type { ReleaseInfo } from './releases.ts';
import { docsUrl } from './urls.ts';

/** A sidebar entry: a page by slug, an autogenerated folder, or a labelled group of entries. */
export type DocsSidebarItem =
  | { slug: string }
  | { autogenerate: { directory: string } }
  | { label: string; items: DocsSidebarItem[] };

/** One entry of the `starlight-sidebar-topics` configuration. */
export interface DocsTopic {
  label: string;
  link: string;
  items: DocsSidebarItem[];
}

/** Sidebar groups of a project's docs, in display order. */
export const DOC_GROUPS = ['Getting started', 'Reference', 'How-tos', 'Help'] as const;
export type DocGroup = (typeof DOC_GROUPS)[number];

/**
 * Group of a docs page, from its path relative to the docs folder (`howto/app-migrations.md`):
 * the overview and getting-started pages come first, `howto/` pages are how-tos, FAQ, changelog,
 * upgrade and troubleshooting pages are help, and everything else is reference.
 */
export function docGroup(relativePath: string): DocGroup {
  const parts = relativePath.replace(/\.mdx?$/i, '').toLowerCase().split('/');
  const name = parts[parts.length - 1];
  if (parts.length > 1 && /^(howtos?|how-tos?)$/.test(parts[0])) return 'How-tos';
  if (/^(index|readme|getting-started|quickstart)$/.test(name)) return 'Getting started';
  if (/^(faq|changelog|troubleshooting)$/.test(name) || name.startsWith('upgrading')) return 'Help';
  return 'Reference';
}

/** Repo-relative-to-docs paths of the markdown files synced for `repo`, from `<docsRoot>/<repo>/docs`. */
export function syncedDocPaths(repo: string, docsRoot: string = join(process.cwd(), 'src/content/docs')): string[] {
  const dir = join(docsRoot, repo, 'docs');
  if (!existsSync(dir)) return [];
  const walk = (rel: string): string[] =>
    readdirSync(join(dir, rel), { withFileTypes: true }).flatMap((e) => {
      const next = rel ? `${rel}/${e.name}` : e.name;
      return e.isDirectory() ? walk(next) : /\.mdx?$/.test(e.name) ? [next] : [];
    });
  return walk('');
}

/** Sidebar of one project's docs: pages in the spec's groups, empty groups left out. */
export function projectSidebar(repo: string, paths: string[]): DocsSidebarItem[] {
  const rank = (path: string) => (/^(index|readme)\.mdx?$/i.test(path) ? 0 : 1);
  const sorted = [...paths].sort((a, b) => rank(a) - rank(b) || a.localeCompare(b));
  return DOC_GROUPS.flatMap((label) => {
    const items = sorted.filter((p) => docGroup(p) === label).map((p) => ({ slug: docSlug(repo, p) }));
    return items.length > 0 ? [{ label, items }] : [];
  });
}

/**
 * Sidebar topics for the docs: one per project whose release carries synced docs, followed by the
 * committed provisioner guides. The guides topic is always present so every docs page belongs to a topic.
 */
export function sidebarTopics(
  projects: ProjectData[],
  releases: (repo: string) => ReleaseInfo,
  listDocs: (repo: string) => string[] = syncedDocPaths,
): DocsTopic[] {
  const perProject = projects.flatMap((p): DocsTopic[] => {
    const release = releases(p.repo);
    if (!release.docsAvailable) return [];
    return [
      {
        label: release.version ? `${p.repo} · ${release.version}` : p.repo,
        link: docsUrl(p.repo),
        items: projectSidebar(p.repo, listDocs(p.repo)),
      },
    ];
  });
  return [
    ...perProject,
    {
      label: 'Provisioners guides',
      link: '/provisioners/guides/',
      items: [{ autogenerate: { directory: 'provisioners/guides' } }],
    },
  ];
}
